data.jsonataExpression:
/* Open-Meteo's place search: no key needed. */
{
    "url": "https://geocoding-api.open-meteo.com/v1/search?count=1&language=en&format=json&name=" & $encodeUrlComponent(place) & (countryCode ? "&countryCode=" & $uppercase(countryCode) : ""),
    "dataType": "json"
}

(
    $found := results[0];
    $found
        ? {
            "url": "https://api.open-meteo.com/v1/forecast?latitude=" & $string($found.latitude) & "&longitude=" & $string($found.longitude) & "&current=temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,wind_speed_10m_max&timezone=auto&forecast_days=7",
            "dataType": "json"
        }
        : $error("Open-Meteo knows no place by that name. Try the full name of the city or town, or add its country.")
)

/* The place and its forecast as Markdown, weather codes in words; the chat's AI Buddy answers the question from it. */
(
    $codes := {"0":"clear sky","1":"mainly clear","2":"partly cloudy","3":"overcast","45":"fog","48":"freezing fog","51":"light drizzle","53":"drizzle","55":"heavy drizzle","56":"light freezing drizzle","57":"freezing drizzle","61":"light rain","63":"rain","65":"heavy rain","66":"light freezing rain","67":"freezing rain","71":"light snow","73":"snow","75":"heavy snow","77":"snow grains","80":"light showers","81":"showers","82":"heavy showers","85":"light snow showers","86":"snow showers","95":"thunderstorm","96":"thunderstorm with hail","99":"thunderstorm with heavy hail"};
    $sky := function($code) {$lookup($codes, $string($code))};
    $where := $[$exists(results)][0].results[0];
    $f := $[$exists(daily)][0];
    $now := $f.current;
    $days := $f.daily;
    $chance := function($percent) {$type($percent) = "number" ? " (" & $string($percent) & " %)" : ""};
    $day := function($date, $i) {
        $fromMillis($toMillis($date), "[FNn,3-3] [D] [MNn,3-3]") & ($i = 0 ? " (today)" : ($i = 1 ? " (tomorrow)" : ""))
    };
    $rows := $map($days.time, function($date, $i) {
        "| " & $day($date, $i) & " | " & $sky($days.weather_code[$i])
            & " | " & $days.temperature_2m_min[$i] & " / " & $days.temperature_2m_max[$i] & " °C"
            & " | " & $days.precipitation_sum[$i] & " mm" & $chance($days.precipitation_probability_max[$i])
            & " | " & $days.wind_speed_10m_max[$i] & " km/h |"
    });
    "**" & $join([$where.name, $where.admin1, $where.country], ", ") & "**, now (" & $substringAfter($now.time, "T") & " local time): "
        & $sky($now.weather_code) & ", " & $now.temperature_2m & " °C (feels like " & $now.apparent_temperature & " °C), humidity "
        & $now.relative_humidity_2m & " %, precipitation " & $now.precipitation & " mm, wind " & $now.wind_speed_10m & " km/h.\n\n"
        & "| Day | Sky | Min / max | Precipitation (chance) | Max wind |\n|---|---|---|---|---|\n" & $join($rows, "\n")
        & "\n\nWeather data by Open-Meteo.com"
)
